echo "         Total execs : $((TOTAL_EXECS / 1000 / 1000)) million"
echo "    Cumulative speed : $TOTAL_EPS execs/sec"
echo "       Pending paths : $TOTAL_PFAV faves, $TOTAL_PENDING total"

